const nextConfig = {
  reactStrictMode: true,
};

export default nextConfig;

import type { Metadata } from "next";
import "./globals.css";
import { AuthProvider } from "@/components/providers/AuthProvider";

export const metadata: Metadata = {
  title: "StewardOS — Personal Operating System",
  description: "Your personal operating system for consistency, truth, and execution.",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className="dark">
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
        <link
          href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,600;1,6..72,400;1,6..72,600&family=JetBrains+Mono:wght@400;500;600&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap"
          rel="stylesheet"
        />
      </head>
      <body className="bg-[#0A0A0A] text-[#E0E0E0] antialiased selection:bg-[#5FBF8C] selection:text-black">
        <AuthProvider>{children}</AuthProvider>
      </body>
    </html>
  );
}

import App from "@/App";

export default function HomePage() {
  return <App />;
}

@import "tailwindcss";

@layer base {
  body {
    font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background-color: #0A0A0A;
    color: #E0E0E0;
  }

  .font-serif-heading {
    font-family: 'Fraunces', 'Newsreader', Georgia, serif;
    letter-spacing: 0.03em;
  }

  .font-serif-body {
    font-family: 'Newsreader', Georgia, serif;
  }

  .font-mono-code {
    font-family: 'JetBrains Mono', monospace;
  }
}

/* Custom scrollbar matching the Sophisticated Dark theme */
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: #0A0A0A;
}
::-webkit-scrollbar-thumb {
  background: #262626;
  border-radius: 2px;
}
::-webkit-scrollbar-thumb:hover {
  background: #5FBF8C;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/** @type {import('postcss-load-config').Config} */
const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;
